# Generated by `mite har` from sample.har.
#
# Kept 9 requests to:
#   api.shop.example (7)
#   www.shop.example (2)
# Dropped 6 static assets and CORS preflights (--include-static keeps them).
# Dropped 2 requests to hosts not in --host:
#   analytics.example-ads.test (2)
#
# Values that looked like credentials or personal data were removed
# from the recording. Set them before running:
#   export MITE_CONF_email=...
#   export MITE_CONF_password=...
#   export MITE_CONF_x_api_token=...
#   export MITE_CONF_authorization=...
# Tokens the application issues during the journey, for example at
# login, must be set the same way for now.
#
# Run the journey once:
#   mite journey test <module>:journey
# Run it under load (edit TARGET_TPS and DURATION_S below):
#   mite scenario test <module>:scenario
# <module> is this file's name without .py; run from its directory.

import math
from urllib.parse import quote

from mite import ensure_fixed_separation
from mite.exceptions import MiteError
from mite.volume_model import Constant
from mite_browser import browser_decorator
from mite_http.checks import check_status_code


# Load settings: edit these to change the test.
TARGET_TPS = 1  # requests per second across all running journeys
DURATION_S = 300

# One journey in the recording makes this many requests. It takes at
# least this long because of the separations below.
REQUESTS_PER_JOURNEY = 9
SECONDS_PER_JOURNEY = 9.0


def _config(ctx, key):
    value = ctx.config.get(key)
    if value is None:
        raise MiteError(f"Missing config {key!r}: set MITE_CONF_{key}")
    return value


@browser_decorator()
async def journey(ctx):
    # Page 1: https://www.shop.example/
    async with ensure_fixed_separation(1.0):
        async with ctx.transaction('Page 1 | GET www.shop.example/'):
            resp = await ctx.browser.get(
                'https://www.shop.example/',
                headers={
                    'accept': 'text/html',
                    'user-agent': 'Mozilla/5.0',
                },
            )
            check_status_code(resp, 200)

    async with ensure_fixed_separation(1.0):
        async with ctx.transaction('Page 1 | POST api.shop.example/api/login'):
            resp = await ctx.browser.post(
                'https://api.shop.example/api/login',
                headers={
                    'content-type': 'application/json',
                },
                data='{"email":"' + _config(ctx, 'email') + '","password":"' + _config(ctx, 'password') + '"}',
            )
            check_status_code(resp, 200)

    async with ensure_fixed_separation(1.0):
        async with ctx.transaction('Page 1 | GET api.shop.example/api/items'):
            resp = await ctx.browser.get(
                'https://api.shop.example/api/items?session_token=' + _config(ctx, 'x_api_token') + '&page=1',
                headers={
                    'x-api-token': _config(ctx, 'x_api_token'),
                    'authorization': _config(ctx, 'authorization'),
                    'accept': 'application/json',
                },
            )
            check_status_code(resp, 200)

    async with ensure_fixed_separation(1.0):
        async with ctx.transaction('Page 1 | GET api.shop.example/old'):
            resp = await ctx.browser.get(
                'https://api.shop.example/old',
                headers={},
            )
            check_status_code(resp, 200)

    # Page 2: https://www.shop.example/basket?email=<email>
    async with ensure_fixed_separation(1.0):
        async with ctx.transaction('Page 2 | GET www.shop.example/basket'):
            resp = await ctx.browser.get(
                'https://www.shop.example/basket?email=' + quote(_config(ctx, 'email'), safe=""),
                headers={},
            )
            check_status_code(resp, 200)

    async with ensure_fixed_separation(1.0):
        async with ctx.transaction('Page 2 | PUT api.shop.example/api/basket/1'):
            resp = await ctx.browser.put(
                'https://api.shop.example/api/basket/1',
                headers={
                    'content-type': 'application/x-www-form-urlencoded',
                },
                data='name=tea&n=2',
            )
            check_status_code(resp, 200)

    async with ensure_fixed_separation(1.0):
        async with ctx.transaction('Page 2 | GET api.shop.example/api/basket'):
            resp = await ctx.browser.get(
                'https://api.shop.example/api/basket',
                headers={},
            )
            check_status_code(resp, (200, 304))

    async with ensure_fixed_separation(1.0):
        async with ctx.transaction('Page 2 | DELETE api.shop.example/api/basket/1'):
            resp = await ctx.browser.delete(
                'https://api.shop.example/api/basket/1',
                headers={},
            )
            check_status_code(resp, 204)

    # Requests not linked to a page
    async with ensure_fixed_separation(1.0):
        async with ctx.transaction('HEAD api.shop.example/health'):
            resp = await ctx.browser.head(
                'https://api.shop.example/health',
                headers={},
            )
            check_status_code(resp, 200)


def scenario():
    # Each running journey makes about
    # REQUESTS_PER_JOURNEY / SECONDS_PER_JOURNEY requests per second.
    # Constant's `tps` is the number of journeys running at once.
    journeys = 1
    if SECONDS_PER_JOURNEY:
        journeys = max(
            1, math.ceil(TARGET_TPS * SECONDS_PER_JOURNEY / REQUESTS_PER_JOURNEY)
        )
    return [[f"{__name__}:journey", None, Constant(duration=DURATION_S, tps=journeys)]]
